CAT_KEYWORDS = {
    "表征/测试": ["表征", "测试", "谱", "电镜", "衍射", "EIS", "GITT", "CV", "LSV",
              "XRD", "XPS", "SEM", "TEM", "Raman", "NMR", "滴定", "色谱", "Mössbauer",
              "AFM", "BET", "显微", "成像", "循环伏安"],
    "合成/工艺": ["合成", "制备", "工艺", "包覆", "沉积", "煅烧", "水热", "溶胶",
              "打印", "制造", "组装", "再生", "前驱体", "活化", "电镀", "烧结"],
    "计算/模拟": ["计算", "模拟", "DFT", "MD", "机器学习", "势函数", "第一性原理",
              "生成式", "生成", "图神经", "知识图谱", "主动学习", "贝叶斯", "筛选",
              "预测", "语言模型", "LLM", "智能体", "描述符", "表征学习", "基因组",
              "高通量计算", "CSP"],
}
# L1 的分类标签归一到 L2 的四值，避免同一库两套取值
CAT_MAP = {"合成/工艺": "合成", "表征/测试": "表征", "计算/模拟": "计算"}

TECHNIQUES = ["SEM", "TEM", "XRD", "XPS", "EIS", "NMR", "Raman", "FTIR", "XANES",
              "EXAFS", "AFM", "BET", "DSC", "TGA", "CV", "LSV", "GCD", "DEMS",
              "GITT", "EBSD", "PXRD", "Mössbauer", "ICP", "XRF", "SIMS"]

EQUIPMENT = ["电化学工作站", "手套箱", "管式炉", "马弗炉", "球磨机", "磁控溅射",
             "离心机", "冷冻干燥", "旋涂仪", "打印机", "机器人", "显微镜", "衍射仪",
             "光谱仪", "色谱仪", "质谱仪", "热重分析仪", "比表面分析仪", "压片机",
             "裁片机", "封装机", "涂布机", "辊压机", "匀浆机", "搅拌器", "超声清洗机"]

PARAM_RE = re.compile(
    r"(?<![A-Za-z0-9\-])"
    r"(\d+(?:\.\d+)?(?:\s*[–\-~至]\s*\d+(?:\.\d+)?)?)\s*"
    r"(mV|μV|V|mA|A|mAh|Hz|kHz|MHz|μHz|°C|℃|min|h|s|nm|μm|mm|rpm|MPa|GPa|"
    r"wt%|at%|mol%|M|mol/L)(?![A-Za-z])")

HEAD_RE = re.compile(r"^#{2,6}\s+(.*)$")
NUM_ITEM_RE = re.compile(r"^\s*\d+[.、)]\s+(.+)$")
BULLET_RE = re.compile(r"^\s*[-*]\s+(.+)$")


# ---------------------------------------------------------------- 基础

def load_config(path=None):
    import yaml
    p = path or os.path.join(K.VAULT, CONFIG_REL)
    with open(p, "r", encoding="utf-8") as f:
        return yaml.safe_load(f) or {}


def norm_ws(s):
    return re.sub(r"\s+", " ", s or "").strip()


def category_scores(name, summary):
    """名称匹配权重 3、摘要权重 1；返回各类得分（用于透明化 + 定类）。"""
    return {cat: 3 * sum(1 for k in kws if k in name)
            + sum(1 for k in kws if k in summary)
            for cat, kws in CAT_KEYWORDS.items()}


def classify_category(name, summary):
    scores = category_scores(name, summary)
    best = max(scores, key=lambda c: scores[c]) if scores else ""
    return best if scores.get(best, 0) >= 2 else "其他"


def extract_techniques(body):
    return [t for t in TECHNIQUES if t in body]


def extract_equipment(body):
    return [e for e in EQUIPMENT if e in body]


def extract_parameters(body, max_params=20, window=40):
    """值+单位+**原文上下文**（上下文用于人工核对，也用于 verbatim 回查）。"""
    out, seen = [], set()
    nb = norm_ws(body)
    for m in PARAM_RE.finditer(body):
        value, unit = m.group(1), m.group(2)
        ctx = norm_ws(body[max(0, m.start() - window): m.end() + window])
        if not ctx:
            continue
        key = (value, unit, ctx)
        if key in seen:
            continue
        seen.add(key)
        out.append({"value": value.strip(), "unit": unit, "context": ctx})
        if len(out) >= max_params:
            break
    return out


def _sections(body):
    """yield (heading, [lines])。"""
    cur, buf = "", []
    for line in body.split("\n"):
        m = HEAD_RE.match(line)
        if m:
            if cur or buf:
                yield cur, buf
            cur, buf = m.group(1).strip(), []
        else:
            buf.append(line)
    yield cur, buf


def extract_steps(body, sections, max_steps=10):
    out = []
    for heading, lines in _sections(body):
        if not any(k in heading for k in sections):
            continue
        for line in lines:
            m = NUM_ITEM_RE.match(line)
            if m:
                out.append({"order": len(out) + 1, "text": norm_ws(m.group(1))})
                if len(out) >= max_steps:
                    return out
    return out


def extract_pitfalls(body, sections, max_pitfalls=5):
    out = []
    for heading, lines in _sections(body):
        if not any(k in heading for k in sections):
            continue
        for line in lines:
            m = BULLET_RE.match(line) or NUM_ITEM_RE.match(line)
            if m:
                txt = norm_ws(m.group(1))
                if 5 <= len(txt) <= 300:
                    out.append(txt)
                if len(out) >= max_pitfalls:
                    return out
    return out


def name_en_of(aliases):
    for a in aliases or []:
        a = str(a).strip()
        if len(a) >= 4 and sum(1 for ch in a if ch.isascii()) / len(a) > 0.8:
            return a
    return ""


def build_records(concepts_dir, cfg, limit=None):
    ex = (cfg.get("extraction") or {})
    ccfg = ex.get("concept") or {}
    min_signals = int(ccfg.get("min_signals", 2))
    max_steps = int(ccfg.get("max_steps", 10))
    max_params = int(ccfg.get("max_params", 20))
    max_pitfalls = int(ccfg.get("max_pitfalls", 5))
    sections = ccfg.get("sections") or ["流程", "步骤", "操作", "协议", "实验", "制备", "合成"]
    pit_sections = ccfg.get("pitfall_sections") or ["警示", "陷阱", "注意事项", "局限", "坑"]

    records, skipped = [], []
    for f in sorted(os.listdir(concepts_dir)):
        if not f.endswith(".md"):
            continue
        path = os.path.join(concepts_dir, f)
        text = K.read_text(path)
        raw, body = K.split_frontmatter(text)
        fm = K.parse_frontmatter(raw)
        name = f[:-3]
        summary = str(fm.get("summary") or "")
        cat_raw = classify_category(name, summary)
        cat = CAT_MAP.get(cat_raw, cat_raw)
        tech = extract_techniques(body)
        equip = extract_equipment(body)
        params = extract_parameters(body, max_params=max_params)
        steps = extract_steps(body, sections, max_steps=max_steps)
        pitfalls = extract_pitfalls(body, pit_sections, max_pitfalls=max_pitfalls)
        signals = sum([bool(tech), bool(equip), len(params) >= 2, bool(steps)])
        if cat_raw == "其他" or signals < min_signals:
            skipped.append({"page": name, "category": cat_raw, "signals": signals})
            continue
        aliases = fm.get("aliases")
        if isinstance(aliases, str):
            aliases = [aliases]
        rec = {
            "method_id": f"concept:{name}",
            "name_zh": name,
            "name_en": name_en_of(aliases),
            "category": cat,
            "category_raw": cat_raw,
            "category_scores": category_scores(name, summary),
            "tier": "concept",
            "source_ref": f"[[concepts/{name}.md]]",
            "page_path": f"wiki/concepts/{name}.md",
            "updated": str(fm.get("updated") or ""),
            "evidence_base": str(fm.get("evidence_base") or ""),
            "summary": summary,
            "equipment": [{"type": e} for e in equip],
            "parameters_raw": params,
            "steps": steps,
            "characterization": tech,
            "pitfalls": pitfalls,
            "extraction_confidence": "high" if (steps or len(params) >= 5) else "medium",
            "reviewed": False,
            "extractor": "rule",
            "extracted_at": datetime.date.today().isoformat(),
            "_body": body,          # 仅用于 verbatim 回查，写盘前剔除
        }
        records.append(rec)

    # 逐字回查：所有提取串必须能在原文（空白归一后）找到
    for r in records:
        nb = norm_ws(r["_body"])
        checks = [p["context"] for p in r["parameters_raw"]]
        checks += [s["text"] for s in r["steps"]]
        checks += r["pitfalls"]
        checks += r["characterization"] + [e["type"] for e in r["equipment"]]
        r["verbatim_ok"] = all(c in nb for c in checks)
        del r["_body"]

    if limit:
        records.sort(key=lambda r: (-len(r["parameters_raw"]), -len(r["steps"]), r["name_zh"]))
        records = records[:int(limit)]
    return records, skipped


def build_db(concepts_dir, cfg, existing=None):
    records, skipped = build_records(concepts_dir, cfg)
    # 重建 L1 时保留已有 L2（source 卡）记录，避免一次概念页重跑把 LLM 提取成果抹掉
    kept_l2 = [m for m in (existing or {}).get("methods") or []
               if m.get("tier") == "source"]
    methods = records + kept_l2
    by_cat, by_conf = {}, {}
    for r in methods:
        by_cat[r["category"]] = by_cat.get(r["category"], 0) + 1
        by_conf[r["extraction_confidence"]] = by_conf.get(r["extraction_confidence"], 0) + 1
    return {
        "meta": {
            "generated_at": datetime.date.today().isoformat(),
            "source": "wiki/concepts/*.md + wiki/sources/*.md",
            "extractor": "rule v0（L1，逐字）+ llm（L2，quote 校验）",
            "pages_scanned": len([f for f in os.listdir(concepts_dir) if f.endswith(".md")]),
            "records": len(methods),
            "l1_records": len(records),
            "l2_records_kept": len(kept_l2),
            "skipped": len(skipped),
            "by_category": by_cat,
            "by_confidence": by_conf,
            "verbatim_ok": sum(1 for r in records if r.get("verbatim_ok")),
            "note": ("L1 只做概念页逐字提取；parameters_raw 是「值+单位+原文上下文」，"
                     "**不做参数重要性判断**——出现即记（可能来自被引案例），"
                     "是否关键参数留 L2/L3。category 为关键词语义打分（含 category_scores），"
                     "不是人工定类。重建 L1 会保留已有 L2 记录。"),
        },
        "methods": methods,
    }


def out_path(cfg, override=None):
    if override:
        return os.path.abspath(override)
    rel = (cfg.get("sci") or {}).get("methods_db") or \
        "projects/sci-assistant/knowledge/methods_db.json"
    return os.path.join(K.VAULT, rel)


def write_db(path, db):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    text = json.dumps(db, ensure_ascii=False, indent=2)
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write(text + "\n")
    with open(path, encoding="utf-8") as f:
        back = json.load(f)
    if len(back.get("methods") or []) != len(db.get("methods") or []):
        raise SystemExit(f"[!] 写盘复算失败: {path}")
    return path


# ---------------------------------------------------------------- L2：source 卡（子 agent 提取 + 校验合并）
L2_SCHEMA_SPEC = """L2 提取 schema（每张卡一条记录）：
{
  "card": "<source 卡名，不含 .md>",
  "name_zh": "该方法的中文名（用原文术语，勿自造）",
  "name_en": "英文名（可空）",
  "category": "合成|表征|测试|计算",
  "materials":      [{"name": "", "amount": "", "role": "", "quote": "逐字原文"}],
  "equipment":      [{"type": "", "model": "", "quote": "逐字原文"}],
  "parameters":     [{"name": "", "value": "", "unit": "", "quote": "逐字原文"}],
  "steps":          [{"order": 1, "action": "", "detail": "", "quote": "逐字原文"}],
  "characterization":[{"technique": "", "quote": "逐字原文"}],
  "key_metrics":    [{"metric": "", "value": "", "unit": "", "condition": "", "quote": "逐字原文"}],
  "no_method": false,
  "no_method_reason": "若该卡没有可提取的方法，填原因"
}
🔴 每个字段值都必须有 quote，且 quote 必须是卡片正文的**连续子串**（空白差异会被归一化）；
   找不到原文依据就不要写该字段。宁缺勿造。"""


def topic_dir_of(topic):
    return os.path.join(K.VAULT, "projects/sci-assistant/topics", topic)


BAD_CARD_RE = re.compile(r"综述|[Mm]ini-?review|[Rr]eview|WeChat|公众号|微信")


def select_l2_cards(topic=None, limit=48, query=None, min_hits=1, sources_dir=None):
    """选卡：给 topic 走该方向的 landscape.json；给 query 则跨全库按技术词命中选卡。

    query 选卡是为「表征方法补全」这类**跨方向**需求准备的：表征技术散落在所有方向里，
    绑死某个方向会系统性漏掉（诊断意见 #1 短板 1 的成因）。
    """
    if query:
        q_terms = [t for t in re.split(r"[\s,，;；]+", query) if t]
        d = sources_dir or os.path.join(K.VAULT, "wiki/sources")
        cands = []
        for fn in sorted(os.listdir(d)):
            if not fn.endswith(".md"):
                continue
            name = fn[:-3]
            if BAD_CARD_RE.search(name):
                continue
            body = K.read_text(os.path.join(d, fn))
            hit_terms = [t for t in q_terms if t in body]
            if len(hit_terms) < int(min_hits):
                continue
            hits = sum(body.count(t) for t in q_terms)
            cands.append({"name": name, "path": f"wiki/sources/{fn}",
                          "score": hits, "techniques": hit_terms})
        cands.sort(key=lambda c: (-len(c["techniques"]), -c["score"], c["name"]))
        return cands[:int(limit)]
    p = os.path.join(topic_dir_of(topic), "landscape.json")
    if not os.path.isfile(p):
        raise SystemExit(f"[!] 缺少 {p}")
    with open(p, encoding="utf-8") as f:
        land = json.load(f)
    cards = [c for c in (land.get("candidates") or [])
             if not BAD_CARD_RE.search(c.get("name") or "")]
    return cards[:int(limit)]


def plan_l2(topic=None, limit=48, batch_size=8, out_dir=None, query=None,
            min_hits=1, sources_dir=None):
    cards = select_l2_cards(topic=topic, limit=limit, query=query,
                            min_hits=min_hits, sources_dir=sources_dir)
    batches = [cards[i:i + batch_size] for i in range(0, len(cards), batch_size)]
    os.makedirs(out_dir, exist_ok=True)
    manifest = {
        "generated_at": datetime.date.today().isoformat(),
        "topic": topic or f"query:{query}",
        "selector": {"kind": "query" if query else "topic",
                     "query": query, "min_hits": int(min_hits) if query else None},
        "schema": L2_SCHEMA_SPEC,
        "total_cards": len(cards),
        "batch_size": batch_size,
        "batches": [{"batch_id": f"batch_{i + 1:02d}",
                     "cards": [{"name": c["name"], "path": c["path"],
                                "score": c.get("score"),
                                "techniques": c.get("techniques")} for c in b]}
                    for i, b in enumerate(batches)],
    }
    path = os.path.join(out_dir, "manifest.json")
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write(json.dumps(manifest, ensure_ascii=False, indent=2) + "\n")
    return path, manifest


def _card_body(name, sources_dir=None):
    d = sources_dir or os.path.join(K.VAULT, "wiki/sources")
    p = os.path.join(d, name + ".md")
    if not os.path.isfile(p):
        return None
    return norm_ws(K.read_text(p))


def validate_l2_record(rec, body_norm):
    """返回 (clean_record, stats)。quote 不是原文连续子串的条目一律丢掉。"""
    if body_norm is None:
        return None, {"error": "card_missing"}
    stats = {"checked": 0, "failed": 0, "dropped": 0}
    clean = {"card": rec.get("card"), "name_zh": (rec.get("name_zh") or "").strip(),
             "name_en": (rec.get("name_en") or "").strip(),
             "category": rec.get("category"),
             "no_method": bool(rec.get("no_method")),
             "no_method_reason": rec.get("no_method_reason") or ""}
    if clean["category"] not in ("合成", "表征", "测试", "计算"):
        stats["error"] = "bad_category"
        return None, stats
    if clean["no_method"]:
        return clean, stats
    if not clean["name_zh"]:
        stats["error"] = "missing_name"
        return None, stats
    for key in ("materials", "equipment", "parameters", "steps",
                "characterization", "key_metrics"):
        items = []
        for it in (rec.get(key) or []):
            if not isinstance(it, dict):
                continue
            q = norm_ws(str(it.get("quote") or ""))
            stats["checked"] += 1
            if not q or q not in body_norm:
                stats["failed"] += 1
                stats["dropped"] += 1
                continue
            items.append(it)
        clean[key] = items
    if not any(clean[k] for k in ("materials", "equipment", "parameters",
                                  "steps", "characterization", "key_metrics")):
        stats["error"] = "no_valid_items"
        return None, stats
    return clean, stats


def merge_l2(merge_dir, cfg, db_path=None, sources_dir=None):
    manifest_p = os.path.join(merge_dir, "manifest.json")
    if not os.path.isfile(manifest_p):
        raise SystemExit(f"[!] 缺少 {manifest_p}")
    with open(manifest_p, encoding="utf-8") as f:
        manifest = json.load(f)
    files = sorted(f for f in os.listdir(merge_dir) if f.startswith("batch_")
                   and f.endswith(".json"))
    if not files:
        raise SystemExit(f"[!] {merge_dir} 下没有 batch_*.json")

    db_p = db_path or out_path(cfg)
    existing = {"methods": [], "meta": {}}
    if os.path.isfile(db_p):
        with open(db_p, encoding="utf-8") as f:
            existing = json.load(f)
    by_id = {m["method_id"]: m for m in existing.get("methods") or []}

    accepted, rejected, total_stats = [], [], {"checked": 0, "failed": 0}
    seen_cards = set()
    for fn in files:
        with open(os.path.join(merge_dir, fn), encoding="utf-8") as f:
            payload = json.load(f)
        records = payload if isinstance(payload, list) else (payload.get("records") or [])
        for rec in records:
            card = (rec.get("card") or "").strip()
            body = _card_body(card, sources_dir) if card else None
            clean, stats = validate_l2_record(rec, body)
            total_stats["checked"] += stats.get("checked", 0)
            total_stats["failed"] += stats.get("failed", 0)
            if not clean:
                rejected.append({"card": card, "reason": stats.get("error")
                                 or "invalid", "batch": fn})
                continue
            mk = f"source:{card}"
            # 同一张卡允许「不同类别」各留一条（如既有合成、再补表征）；
            # 同类别重复仍按 duplicate 拒收，保证重跑幂等。
            if mk in by_id and clean.get("category") != by_id[mk].get("category"):
                mk = f"{mk}#{clean.get('category')}"
            clean.update({
                "method_id": mk,
                "tier": "source",
                "source_ref": f"[[sources/{card}]]",
                "page_path": f"wiki/sources/{card}.md",
                "extraction_confidence": "medium",
                "reviewed": False,
                "extractor": f"llm:{fn[:-5]}",
                "extracted_at": datetime.date.today().isoformat(),
                "validation": {"quotes_checked": stats["checked"],
                               "quotes_failed": stats["failed"]},
            })
            if clean.get("no_method"):
                rejected.append({"card": card, "reason": "no_method",
                                 "batch": fn, "detail": clean.get("no_method_reason", "")})
                continue
            if mk in by_id:
                rejected.append({"card": card, "reason": "duplicate", "batch": fn})
                continue
            by_id[mk] = clean
            accepted.append(clean)
            seen_cards.add(card)

    methods = list(by_id.values())
    by_cat, by_conf = {}, {}
    for m in methods:
        by_cat[m.get("category")] = by_cat.get(m.get("category"), 0) + 1
        by_conf[m.get("extraction_confidence")] = by_conf.get(m.get("extraction_confidence"), 0) + 1
    with_val = [m for m in methods if isinstance(m.get("validation"), dict)]
    cum_checked = sum((m.get("validation") or {}).get("quotes_checked", 0) for m in with_val)
    cum_failed = sum((m.get("validation") or {}).get("quotes_failed", 0) for m in with_val)
    db = {
        "meta": {
            "generated_at": datetime.date.today().isoformat(),
            "source": "wiki/concepts/*.md + wiki/sources/*.md",
            "extractor": "rule v0（L1，逐字） + llm（L2，quote 校验）",
            "records": len(methods),
            "by_category": by_cat,
            "by_confidence": by_conf,
            "l2": {
                "topic": manifest.get("topic"),
                "batches": len(files),
                "accepted": len(accepted),
                "rejected": len(rejected),
                "run_quotes_checked": total_stats["checked"],
                "run_quotes_failed": total_stats["failed"],
                "cumulative_quotes_checked": cum_checked,
                "cumulative_quotes_failed": cum_failed,
                "cumulative_records": len(with_val),
                "cumulative_note": ("run_* 只统计本次合并；cumulative_* 汇总库内带 validation 字段的 "
                                    "L2 记录（早期无该字段的 L2 不计入）。"),
                "rejected_detail": rejected,
            },
            "note": ("L1 为概念页逐字提取；L2 为 LLM 从 source 卡提取，"
                     "**每条必须有原文 quote 且通过连续子串校验**，否则丢弃。"
                     "L2 记录 reviewed=false，用于策略层；操作层须人工复核或走 L3。"),
        },
        "methods": methods,
    }
    write_db(db_p, db)
    return db, accepted, rejected, total_stats


def _squash(s):
    s = re.sub(r"\s+", "", str(s or ""))
    return s.replace("–", "-").replace("−", "-").replace("→", "-").replace("~", "-")


def _nums(s):
    return re.findall(r"\d+(?:\.\d+)?", str(s or ""))


def recheck_db(db_path):
    """对已有库重跑「数值是否在自身 quote 里」检查，只打标不改值。

    quote 级校验保证「引文是真的」，但不保证「value 写在引文里」——
    实测 594 条数值条目里 17 条（2.9%）的 value 数字不在 quote（多为引文截断）。
    这些条目标 value_in_quote=false，供 C2 过滤；不删除，便于人工回查。
    """
    with open(db_path, encoding="utf-8") as f:
        db = json.load(f)
    bad = 0
    for m in db.get("methods") or []:
        if m.get("tier") != "source":
            continue
        for fld, key in (("parameters", "value"), ("key_metrics", "value"),
                         ("materials", "amount")):
            for it in m.get(fld) or []:
                val = str(it.get(key) or "")
                if not val:
                    continue
                q = _squash(it.get("quote"))
                ok = all(n in q for n in _nums(val))
                it["value_in_quote"] = ok
                if not ok:
                    bad += 1
    db.setdefault("meta", {}).setdefault("l2", {})["value_unsupported"] = bad
    write_db(db_path, db)
    return db, bad


def _selftest():
    fails = []

    def chk(label, cond, detail=""):
        print(("  ok   " if cond else "  FAIL ") + label +
              (f"   [{detail}]" if detail and not cond else ""))
        if not cond:
            fails.append(label)

    tmp = K.make_temp_dir(prefix="sci_method_")
    try:
        good = """---
type: concept
summary: 水热合成制备正极材料的方法
evidence_base: mixed
aliases: [hydrothermal synthesis, 水热法]
---
# 水热合成

采用水热合成制备 LiFePO4，反应温度 180 °C，保温 12 h。
表征手段包括 XRD、SEM。

## 流程

1. 将前驱体溶于去离子水，搅拌 30 min
2. 转入反应釜，180 °C 保温 12 h

## 注意事项

- 釜内填充度不得超过 80%，否则压力过高
"""
        other = """---
type: concept
summary: 用图结构组织材料知识
---
# 材料知识图谱

只讨论三元组与图查询，不是实验方法。
"""
        eis = """---
type: concept
summary: 施加交流扰动测阻抗的频域方法
evidence_base: strong
---
# EIS

扰动幅度 5–10 mV，频率范围 10 μHz–1 MHz，用 EIS 分离过程。
"""
        for name, text in (("水热合成.md", good), ("材料知识图谱.md", other),
                           ("EIS电化学阻抗谱.md", eis)):
            with open(os.path.join(tmp, name), "w", encoding="utf-8", newline="\n") as f:
                f.write(text)

        cfg = {"extraction": {"concept": {"min_signals": 2, "max_steps": 10,
                                          "max_params": 20, "max_pitfalls": 5,
                                          "sections": ["流程"], "pitfall_sections": ["注意事项"]}}}
        records, skipped = build_records(tmp, cfg)
        by_name = {r["name_zh"]: r for r in records}

        chk("分类：水热合成 -> 合成", by_name.get("水热合成", {}).get("category") == "合成")
        chk("分类：知识图谱 -> 其他（被跳过）", "材料知识图谱" not in by_name and
            any(s["page"] == "材料知识图谱" for s in skipped))
        chk("分类：EIS -> 表征", by_name.get("EIS电化学阻抗谱", {}).get("category") == "表征")

        h = by_name["水热合成"]
        chk("字段：技术识别", set(h["characterization"]) == {"XRD", "SEM"})
        chk("字段：参数带原文上下文",
            any(p["unit"] == "°C" and "180" in p["value"] for p in h["parameters_raw"]))
        chk("字段：步骤按编号有序", [s["order"] for s in h["steps"]] == [1, 2])
        chk("字段：步骤文本来自原文", "转入反应釜" in h["steps"][1]["text"])
        chk("字段：警示项被收进 pitfalls", any("填充度" in p for p in h["pitfalls"]))
        chk("字段：英文名从别名取", h["name_en"] == "hydrothermal synthesis")
        chk("字段：verbatim 回查通过", h["verbatim_ok"] is True)
        chk("去重：method_id 唯一", len({r["method_id"] for r in records}) == len(records))

        e = by_name["EIS电化学阻抗谱"]
        chk("字段：EIS 参数含 mV 与 Hz",
            any(p["unit"] == "mV" for p in e["parameters_raw"]) and
            any(p["unit"] in ("Hz", "MHz", "μHz") for p in e["parameters_raw"]))
        chk("字段：EIS 无步骤 + 参数 >=5 才 high；此处 medium",
            e["extraction_confidence"] == "medium")

        # 反例：伪造的上下文必须被 verbatim 抓住
        fake = dict(h)
        fake["parameters_raw"] = [{"value": "999", "unit": "°C",
                                   "context": "原文里根本没有的 999 °C 条件"}]
        fake["steps"] = []
        fake["pitfalls"] = []
        fake["characterization"] = []
        fake["equipment"] = []
        nb = norm_ws(good)
        chk("verbatim：伪造参数被抓出",
            any(c not in nb for c in [p["context"] for p in fake["parameters_raw"]]))

        db = build_db(tmp, cfg)
        chk("汇总：meta 计数与实际一致",
            db["meta"]["records"] == len(records) and
            db["meta"]["verbatim_ok"] == len(records))
        chk("汇总：分类统计存在", db["meta"]["by_category"].get("合成") == 1)

        # 6) L2：quote 校验与合并
        tmp2 = K.make_temp_dir(prefix="sci_l2_")
        try:
            src_dir = os.path.join(tmp2, "sources")
            os.makedirs(src_dir)
            card = "cardA"
            body2 = "采用水热法合成样品，180 °C 保温 12 h，用 XRD 与 SEM 表征。"
            with open(os.path.join(src_dir, card + ".md"), "w",
                      encoding="utf-8", newline="\n") as f:
                f.write(body2)
            merge_dir = os.path.join(tmp2, "jobs")
            os.makedirs(merge_dir)
            with open(os.path.join(merge_dir, "manifest.json"), "w",
                      encoding="utf-8") as f:
                json.dump({"topic": "t", "batches": []}, f)
            rec_good = {"card": card, "name_zh": "水热法", "category": "合成",
                        "parameters": [{"name": "温度", "value": "180", "unit": "°C",
                                        "quote": "180 °C 保温 12 h"}],
                        "characterization": [{"technique": "XRD", "quote": "XRD"}],
                        "steps": [], "materials": [], "equipment": [], "key_metrics": []}
            rec_bad = {"card": "cardB", "name_zh": "伪造", "category": "合成",
                       "parameters": [{"name": "温度", "value": "999", "unit": "°C",
                                       "quote": "999 °C"}],
                       "characterization": [], "steps": [], "materials": [],
                       "equipment": [], "key_metrics": []}
            with open(os.path.join(merge_dir, "batch_01.json"), "w",
                      encoding="utf-8") as f:
                json.dump({"records": [rec_good, rec_bad]}, f, ensure_ascii=False)

            clean, st = validate_l2_record(rec_good, norm_ws(body2))
            chk("L2：合法 quote 通过", clean is not None and st["failed"] == 0)
            clean2, st2 = validate_l2_record(rec_good, norm_ws("完全无关的正文"))
            chk("L2：quote 不在原文 -> 记录被拒", clean2 is None and st2["failed"] >= 1)
            db2, acc, rej, st3 = merge_l2(merge_dir, cfg,
                                          db_path=os.path.join(tmp2, "db.json"),
                                          sources_dir=src_dir)
            chk("L2：合并接受合法卡、拒绝缺卡",
                len(acc) == 1 and any(r["reason"] == "card_missing" for r in rej))
            chk("L2：method_id 带 source 前缀且 source_ref 正确",
                db2["methods"][0]["method_id"] == f"source:{card}" and
                db2["methods"][0]["source_ref"] == f"[[sources/{card}]]")

            # 7) query 选卡（表征补全用）：跨卡按技术词命中排序 + min_hits 过滤 + 排除综述
            for fn, txt in (("cardC.md", "用 EIS 测阻抗。"),
                            ("cardD.md", "只讨论理论，不做实验。"),
                            ("某综述2026.md", "XRD SEM EIS 全都有，但这是综述。")):
                with open(os.path.join(src_dir, fn), "w",
                          encoding="utf-8", newline="\n") as f:
                    f.write(txt)
            sel2 = select_l2_cards(query="XRD SEM EIS", limit=10, min_hits=2,
                                   sources_dir=src_dir)
            chk("选卡：min_hits=2 只留命中两类技术的卡",
                [c["name"] for c in sel2] == ["cardA"], str([c["name"] for c in sel2]))
            chk("选卡：命中技术词列表随卡返回",
                sel2 and set(sel2[0]["techniques"]) == {"XRD", "SEM"})
            sel1 = select_l2_cards(query="XRD SEM EIS", limit=10, min_hits=1,
                                   sources_dir=src_dir)
            chk("选卡：min_hits=1 纳入单技术卡、排除 0 命中卡",
                [c["name"] for c in sel1] == ["cardA", "cardC"],
                str([c["name"] for c in sel1]))
            chk("选卡：综述卡被排除", "某综述2026" not in [c["name"] for c in sel1])
            chk("选卡：0 命中返回空",
                select_l2_cards(query="不存在的技术甲 不存在的技术乙",
                                sources_dir=src_dir) == [])
            man_dir = os.path.join(tmp2, "jobs_q")
            mp, man2 = plan_l2(query="XRD SEM EIS", min_hits=1, batch_size=1,
                               out_dir=man_dir, sources_dir=src_dir)
            chk("选卡：manifest 记录 selector=query 与批次数",
                man2["selector"]["kind"] == "query" and man2["total_cards"] == 2
                and len(man2["batches"]) == 2 and os.path.isfile(mp))
            chk("选卡：批次卡片带 techniques 字段",
                all("techniques" in c for b in man2["batches"] for c in b["cards"]))
        finally:
            K.remove_temp_dir(tmp2)
    finally:
        K.remove_temp_dir(tmp)

    print(f"SELFTEST {'PASSED' if not fails else 'FAILED'}: {len(fails)} failure(s)")
    return 0 if not fails else 1


# ---------------------------------------------------------------- CLI

def main(argv=None):
    ap = argparse.ArgumentParser(description="实验方法结构化提取（Phase 2a：L1 概念页 / L2 source 卡）")
    ap.add_argument("--from", dest="src", default="concepts", choices=["concepts", "sources"],
                    help="提取层级：concepts（规则收割）/ sources（子 agent 提取 + 校验合并）")
    ap.add_argument("--topic", default=None,
                    help="---from sources 用：方向名（读其 landscape.json 选卡）")
    ap.add_argument("--query", default=None,
                    help="---from sources 用：技术词（空格分隔），跨全库 source 卡按命中选卡"
                         "（表征补全用，如 \"EIS XRD SEM XPS\"）")
    ap.add_argument("--min-hits", type=int, default=1,
                    help="---from sources --query 用：至少命中几种技术词（默认 1）")
    ap.add_argument("--out-dir", default=None,
                    help="---from sources --plan 用：批次目录（默认 knowledge/l2_jobs；"
                         "可指定子目录如 knowledge/l2_jobs/表征方法）")
    ap.add_argument("--limit", type=int, default=None,
                    help="---from sources 用：抽多少张卡（默认 48）")
    ap.add_argument("--batch-size", type=int, default=8, help="---from sources --plan 用：每批卡数")
    ap.add_argument("--plan", action="store_true",
                    help="---from sources：生成批次清单（不提交给 LLM，只落 manifest）")
    ap.add_argument("--merge-dir", default=None,
                    help="---from sources：合并该目录下的 batch_*.json（逐条 quote 校验）")
    ap.add_argument("--recheck", action="store_true",
                    help="---from sources：对已有库重跑「value 数字是否在 quote 里」并打标")
    ap.add_argument("--out", default=None, help="输出路径（默认取配置 sci.methods_db）")
    ap.add_argument("--json", action="store_true", help="结果 JSON 打印到 stdout")
    ap.add_argument("--no-write", action="store_true", help="不写盘")
    ap.add_argument("--selftest", action="store_true", help="自检（不依赖知识库）")
    args = ap.parse_args(argv)

    if args.selftest:
        return _selftest()

    cfg = load_config()

    if args.src == "sources":
        if args.recheck:
            db, bad = recheck_db(out_path(cfg, args.out))
            print(f"[ok] 重检：value_in_quote=false {bad} 条；"
                  f"库内共 {db['meta']['records']} 条")
            return 0
        if args.plan:
            if not args.topic and not args.query:
                raise SystemExit("[!] --plan 需要 --topic 或 --query")
            out_dir = args.out_dir or os.path.join(
                K.VAULT, "projects/sci-assistant/knowledge/l2_jobs")
            if not os.path.isabs(out_dir):
                out_dir = os.path.join(K.VAULT, out_dir)
            p, man = plan_l2(topic=args.topic, limit=args.limit or 48,
                             batch_size=args.batch_size, out_dir=out_dir,
                             query=args.query, min_hits=args.min_hits)
            print(f"[ok] 已生成 {len(man['batches'])} 批，共 {man['total_cards']} 张卡"
                  + (f"（query={args.query}，min_hits={args.min_hits}）" if args.query else ""))
            for b in man["batches"]:
                print(f"     {b['batch_id']}: {len(b['cards'])} 张")
            print(f"     清单: {os.path.relpath(p, K.VAULT)}")
            return 0
        if args.merge_dir:
            merge_dir = args.merge_dir if os.path.isabs(args.merge_dir) \
                else os.path.join(K.VAULT, args.merge_dir)
            db, acc, rej, st = merge_l2(merge_dir, cfg, db_path=out_path(cfg, args.out))
            print(f"[ok] 合并：接受 {len(acc)}，拒绝 {len(rej)}；"
                  f"quote 校验 {st['checked']} 条，失败 {st['failed']}")
            for r in rej[:8]:
                print(f"     - {r['card']}: {r['reason']}")
            print(f"     方法库总计: {db['meta']['records']} 条")
            print(f"     输出: {os.path.relpath(out_path(cfg, args.out), K.VAULT)}")
            return 0
        raise SystemExit("[!] --from sources 需要 --plan 或 --merge-dir")

    concepts_dir = os.path.join(K.VAULT, (cfg.get("kb") or {}).get("concepts_dir")
                                or "wiki/concepts")
    existing = None
    db_p = out_path(cfg, args.out)
    if os.path.isfile(db_p):
        with open(db_p, encoding="utf-8") as f:
            existing = json.load(f)
    db = build_db(concepts_dir, cfg, existing=existing)
    if args.limit:
        db["methods"] = db["methods"][:args.limit]
        db["meta"]["records"] = len(db["methods"])
    if args.json:
        print(json.dumps(db, ensure_ascii=False, indent=2))
    if not args.no_write:
        p = write_db(out_path(cfg, args.out), db)
        m = db["meta"]
        l1 = [r for r in db["methods"] if r.get("tier") == "concept"]
        l1_ok = sum(1 for r in l1 if r.get("verbatim_ok"))
        print(f"[ok] 方法库：{m['records']} 条（L1 {len(l1)} / L2 {m['records'] - len(l1)}；"
              f"L1 verbatim {l1_ok}/{len(l1)}）")
        print(f"     分类：{m['by_category']}  置信度：{m['by_confidence']}")
        bad = [r["method_id"] for r in l1 if not r.get("verbatim_ok")]
        if bad:
            print(f"[!] L1 verbatim 回查失败 {len(bad)} 条: {bad[:5]}")
        print(f"     输出: {os.path.relpath(p, K.VAULT)}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
